const PT2EN=new Map(),EN2PT=new Map();PAIRS.forEach(([p,e])=>{PT2EN.set(p,e);EN2PT.set(e,p);});
function trText(s:string,toEn?:boolean){const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/)!,core=m[2];if(!core)return null;if(window.__seen)window.__seen.add(core.replace(/\d+(?:[.,]\d+)?/g,'#'));const map=toEn?PT2EN:EN2PT;let r=map.get(core);
  if(r==null){const nums:string[]=[],k=core.replace(/\d+(?:[.,]\d+)?/g,(x:string)=>{nums.push(x);return'#';}),tpl=nums.length?map.get(k):null;if(tpl!=null){let i=0;r=tpl.replace(/#/g,()=>nums[i++]);}}
  if(r==null)for(const[pt,en,ept,pte]of RULES){const re=toEn?pt:ept,rep=toEn?en:pte;if(re&&rep!=null&&re.test(core)){const x=typeof rep==='string'?core.replace(re,rep):core.replace(re,rep);if(x!==core){r=x;break;}}}
  if(r==null&&toEn&&window.__miss&&/[ãõçáéíóúâêôà]|\b(de|do|da|dos|das|em|para|com|não|uma?|os|as|que|por|ao|ficheiros?|ramo|sem|mais)\b/i.test(core))window.__miss.add(core);
  return r==null?null:m[1]+r+m[3];}
function trAttrs(el:any){for(const a of['title','placeholder']){if(!el.hasAttribute(a))continue;const v=el.getAttribute(a);el._ta=el._ta||{};el._oa=el._oa||{};if(el._ta[a]!==v)el._oa[a]=v;const r=trText(el._oa[a],LOCALE==='en')||el._oa[a];el._ta[a]=r;if(v!==r)el.setAttribute(a,r);}}
function trNode(n:any){if(n.nodeType===3){const v=n.nodeValue;if(n._t!==v)n._o=v;if(!/[A-Za-zÀ-ÿ]/.test(n._o))return;const r=trText(n._o,LOCALE==='en')||n._o;n._t=r;if(v!==r)n.nodeValue=r;}
  else if(n.nodeType===1&&!n.matches(TR_SKIP)){trAttrs(n);for(const c of n.childNodes)trNode(c);}}
function setLocale(l:string){hydrateLocale();window.LOCALE=l;LS.set('locale',l);document.documentElement.lang=l==='en'?'en':'pt-AO';trNode(document.body);const t=tabOf(cur);if(t&&t.kind==='settings')show(cur);}
function i18nBoot(){hydrateLocale();document.documentElement.lang=LOCALE==='en'?'en':'pt-AO';trNode(document.body);
  new MutationObserver(ms=>{for(const m of ms){if(m.type==='childList')m.addedNodes.forEach(n=>{const p=(n.nodeType===1?n:n.parentElement) as Element|null;if(p&&!p.closest(TR_SKIP))trNode(n);});else{const p=(m.target.nodeType===1?m.target:m.target.parentElement) as Element|null;if(!p||p.closest(TR_SKIP))continue;m.type==='characterData'?trNode(m.target):trAttrs(m.target);}}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','placeholder']});}

/* ── LOCALE window-backed + hidratação preguiçosa (ver nota no cabeçalho) ── */
if (window.LOCALE == null) window.LOCALE = "en";
let _locHyd = false;
function hydrateLocale() {
  if (_locHyd) return;
  _locHyd = true;
  try { let l = LS ? LS.get("locale", "en") : "en"; if (!LOCALES.some(x => x[0] === l)) l = "en"; window.LOCALE = l; } catch (e) {}
}

/* ── publicação no window: nomes que o resíduo (app.ts VIEW.settings/CMD),
   os onclick inline e `startup.ts` resolvem como globais. ── */
Object.assign(window, { setLocale, trText, trNode, trAttrs, i18nBoot, LOCALES });
